            f"查询参数 {field} 必须为 UTC 秒精度 Z 时间"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        datetime.strptime(raw, "%Y-%m-%dT%H:%M:%SZ").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, TypeError):
        raise ValidationError(
            f"查询参数 {field} 必须为 UTC 秒精度 Z 时间"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    return raw

